from unittest.mock import patch
import проверка_лицензий


class TestПроверкаЛицензий(unittest.TestCase):
    @patch('проверка_лицензий._проверить_по_сети')
    def test_валидная_лицензия(self, mock_network):
        mock_network.return_value = {'valid': True, 'expired': False}
        result = проверка_лицензий.проверить_лицензию('VALID-KEY-123')
        self.assertTrue(result['valid'])
        self.assertFalse(result['expired'])

    @patch('проверка_лицензий._проверить_по_сети')
    def test_истёкшая_лицензия(self, mock_network):
        mock_network.return_value = {'valid': True, 'expired': True}
        result = проверка_лицензий.проверить_лицензию('EXPIRED-KEY-456')
        self.assertTrue(result['valid'])
        self.assertTrue(result['expired'])

    @patch('проверка_лицензий._проверить_по_сети')
    def test_невалидная_лицензия(self, mock_network):
        mock_network.return_value = {'valid': False, 'expired': False}
        result = проверка_лицензий.проверить_лицензию('INVALID-KEY-789')
        self.assertFalse(result['valid'])
        self.assertFalse(result['expired'])

    @patch('проверка_лицензий._проверить_по_сети', side_effect=Exception('offline'))
    def test_отсутствующая_лицензия_офлайн(self, mock_network):
        result = проверка_лицензий.проверить_лицензию('MISSING-KEY-000')
        self.assertFalse(result['valid'])
        self.assertFalse(result['expired'])


if __name__ == '__main__':
    unittest.main()", "path": "test_проверка_лицензий.py"}

